import { useState, useMemo, type FormEvent } from 'react';
import { Plus, Edit2, Trash2, Search, ChevronLeft, ChevronRight, Loader2, Eye, EyeOff, ArrowUp, ArrowDown, Languages, Upload } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogFooter,
} from '@/components/ui/dialog';
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '@/components/ui/table';
import { Input } from '@/components/ui/input';
import { Switch } from '@/components/ui/switch';
import { Label } from '@/components/ui/label';
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from '@/components/ui/alert-dialog';
import I18nInput from '@/components/I18nInput';
import RichTextEditor from '@/components/RichTextEditor';
import { useNews, type INewsArticle } from '@/hooks/useNews';
import { createI18nText, type I18nText } from '@/lib/i18n-text';
import { batchTranslateI18n } from '@/lib/translate';
import { toast } from 'sonner';
import { useI18n } from '@/i18n/I18nContext';
import PageBreadcrumb from '@/components/PageBreadcrumb';
import { useSyncService } from '@/context/SyncServiceContext';
import SyncStatusBadge from '@/components/SyncStatusBadge';
import { imgPath } from '@/utils/img-path';
import { compressImage } from '@/utils/compress-image';
import { Image } from '@/components/ui/image';

interface NewsForm {
  slug: string;
  coverImage: string;
  title: I18nText;
  summary: I18nText;
  content: I18nText;
  metaTitle: I18nText;
  metaDescription: I18nText;
  publishDate: string;
  published: boolean;
  order: number;
}

const emptyForm = (): NewsForm => ({
  slug: '',
  coverImage: '',
  title: createI18nText(''),
  summary: createI18nText(''),
  content: createI18nText(''),
  metaTitle: createI18nText(''),
  metaDescription: createI18nText(''),
  publishDate: new Date().toISOString().split('T')[0],
  published: true,
  order: 0,
});

const PAGE_SIZE = 10;

export default function AdminNewsPage() {
  const { articles, addArticle, updateArticle, deleteArticle, loading } = useNews();
  const { adminT } = useI18n();
  const { markDirty, syncModule, syncJsonFile, syncImagesInData, getStatus } = useSyncService();
  const syncStatus = getStatus('news');
  const [dialogOpen, setDialogOpen] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [form, setForm] = useState<NewsForm>(emptyForm());
  const [searchQuery, setSearchQuery] = useState('');
  const [currentPage, setCurrentPage] = useState(1);
  const [deleteId, setDeleteId] = useState<string | null>(null);
  const [translating, setTranslating] = useState(false);

  const filteredArticles = useMemo(() => {
    let list = [...articles];
    if (searchQuery.trim()) {
      const q = searchQuery.toLowerCase();
      list = list.filter(
        (a) =>
          a.slug.toLowerCase().includes(q) ||
          a.title.en.toLowerCase().includes(q) ||
          a.title.zh.toLowerCase().includes(q)
      );
    }
    return list;
  }, [articles, searchQuery]);

  const totalPages = Math.max(1, Math.ceil(filteredArticles.length / PAGE_SIZE));
  const paginatedArticles = useMemo(() => {
    const start = (currentPage - 1) * PAGE_SIZE;
    return filteredArticles.slice(start, start + PAGE_SIZE);
  }, [filteredArticles, currentPage]);

  const resetForm = () => {
    setForm(emptyForm());
    setEditingId(null);
  };

  const openCreate = () => {
    resetForm();
    setDialogOpen(true);
  };

  const openEdit = (article: INewsArticle) => {
    setForm({
      slug: article.slug,
      coverImage: article.coverImage,
      title: article.title,
      summary: article.summary,
      content: article.content,
      metaTitle: article.metaTitle,
      metaDescription: article.metaDescription,
      publishDate: article.publishDate,
      published: article.published,
      order: article.order,
    });
    setEditingId(article.id);
    setDialogOpen(true);
  };

  const handleSubmit = async (e: FormEvent) => {
    e.preventDefault();

    if (!form.slug.trim()) {
      toast.error('Please enter the SEO slug');
      return;
    }
    if (!form.title.en.trim()) {
      toast.error('Please enter the English title');
      return;
    }

    try {
      if (editingId) {
        updateArticle(editingId, form);
        markDirty('news');
        toast.success('Article updated successfully');
      } else {
        // Check slug uniqueness
        if (articles.some((a) => a.slug === form.slug)) {
          toast.error('Slug already exists, please use a unique slug');
          return;
        }
        addArticle(form);
        markDirty('news');
        toast.success('Article added successfully');
      }
      setDialogOpen(false);
      resetForm();
    } catch (err) {
      toast.error('Failed to save article: ' + (err instanceof Error ? err.message : String(err)));
    }
  };

  const handleDelete = () => {
    if (!deleteId) return;
    try {
      deleteArticle(deleteId);
      markDirty('news');
      toast.success('Article deleted');
    } catch (err) {
      toast.error('Failed to delete article');
    }
    setDeleteId(null);
  };

  const togglePublished = (id: string, published: boolean) => {
    try {
      updateArticle(id, { published });
      markDirty('news');
      toast.success(published ? 'Article published' : 'Article unpublished');
    } catch {
      toast.error('Failed to update status');
    }
  };

  const moveOrder = (id: string, direction: 'up' | 'down') => {
    const idx = articles.findIndex((a) => a.id === id);
    if (idx === -1) return;
    const targetIdx = direction === 'up' ? idx - 1 : idx + 1;
    if (targetIdx < 0 || targetIdx >= articles.length) return;
    const updated = [...articles];
    const currentOrder = updated[idx].order;
    updated[idx].order = updated[targetIdx].order;
    updated[targetIdx].order = currentOrder;
    try {
      // Directly save without triggering setArticles twice
      // Use updateArticle for both
      updateArticle(updated[idx].id, { order: updated[idx].order });
      updateArticle(updated[targetIdx].id, { order: updated[targetIdx].order });
    } catch {
      toast.error('Failed to reorder');
    }
  };

  const handleTranslate = async () => {
    if (!form.title.en.trim()) {
      toast.error('Please enter English content first');
      return;
    }
    setTranslating(true);
    try {
      const tasks = [
        { label: 'Title', value: form.title },
        { label: 'Summary', value: form.summary },
        { label: 'Content', value: form.content },
        { label: 'Meta Title', value: form.metaTitle },
        { label: 'Meta Description', value: form.metaDescription },
      ].filter((t) => t.value.en.trim());

      const results = await batchTranslateI18n(tasks);

      const resultMap: Record<string, I18nText> = {};
      results.forEach((r) => {
        resultMap[r.label] = r.value;
      });

      setForm((prev) => ({
        ...prev,
        title: resultMap.Title || prev.title,
        summary: resultMap.Summary || prev.summary,
        content: resultMap.Content || prev.content,
        metaTitle: resultMap['Meta Title'] || prev.metaTitle,
        metaDescription: resultMap['Meta Description'] || prev.metaDescription,
      }));

      toast.success('Translation completed');
    } catch (err) {
      toast.error('Translation failed: ' + (err instanceof Error ? err.message : String(err)));
    } finally {
      setTranslating(false);
    }
  };

  const handleCoverUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    if (!file.type.startsWith('image/')) {
      toast.error('Please select an image file');
      return;
    }
    if (file.size > 3 * 1024 * 1024) {
      toast.error('Image must be less than 3MB');
      return;
    }
    try {
      const compressed = await compressImage(file, 1200, 0.72);
      setForm((prev) => ({ ...prev, coverImage: compressed }));
    } catch (err) {
      toast.error('Failed to process image: ' + (err instanceof Error ? err.message : String(err)));
    }
    e.target.value = '';
  };

  return (
    <div className="space-y-6">
      <PageBreadcrumb
        firstItem={{ label: adminT('admin.dashboard'), href: '/admin/dashboard', icon: 'dashboard' }}
        items={[{ label: adminT('admin.news') }]}
      />

      <Card>
        <CardHeader className="flex flex-row items-center justify-between pb-2">
          <div className="flex items-center gap-2">
            <CardTitle className="text-lg font-semibold">News Management</CardTitle>
            <SyncStatusBadge status={syncStatus} />
          </div>
          <div className="flex items-center gap-2">
            <Button
              variant="outline"
              size="sm"
              onClick={() =>
                syncModule('news', 'News', async (config) => {
                  const dataWithImages = await syncImagesInData(
                    config,
                    articles,
                    'news',
                    ['coverImage' as any]
                  );
                  await syncJsonFile(
                    config,
                    'data/news.json',
                    dataWithImages,
                    'Update news data'
                  );
                })
              }
              disabled={syncStatus === 'syncing'}
            >
              <Upload className="size-3.5 mr-1.5" />
              Sync to GitHub
            </Button>
            <Button onClick={openCreate} size="sm">
              <Plus className="size-4 mr-1.5" />
              Add Article
            </Button>
          </div>
        </CardHeader>
        <CardContent className="space-y-4">
          <div className="flex items-center gap-3">
            <div className="relative flex-1 max-w-sm">
              <Search className="pointer-events-none absolute left-3 top-1/2 size-4 -translate-y-1/2 text-muted-foreground" />
              <Input
                placeholder="Search articles..."
                value={searchQuery}
                onChange={(e) => {
                  setSearchQuery(e.target.value);
                  setCurrentPage(1);
                }}
                className="pl-9"
              />
            </div>
            <span className="text-sm text-muted-foreground">
              Total: {filteredArticles.length} articles
            </span>
          </div>

          {loading ? (
            <div className="flex items-center justify-center py-12">
              <Loader2 className="size-6 animate-spin text-primary" />
            </div>
          ) : paginatedArticles.length === 0 ? (
            <div className="text-center py-12 text-muted-foreground text-sm">
              No articles found
            </div>
          ) : (
            <>
              <div className="w-full overflow-x-auto">
                <Table>
                  <TableHeader>
                    <TableRow>
                      <TableHead className="whitespace-nowrap w-12">Order</TableHead>
                      <TableHead className="whitespace-nowrap">Cover</TableHead>
                      <TableHead className="whitespace-nowrap">Title</TableHead>
                      <TableHead className="whitespace-nowrap">Slug</TableHead>
                      <TableHead className="whitespace-nowrap">Publish Date</TableHead>
                      <TableHead className="whitespace-nowrap">Status</TableHead>
                      <TableHead className="whitespace-nowrap text-right">Actions</TableHead>
                    </TableRow>
                  </TableHeader>
                  <TableBody>
                    {paginatedArticles.map((article, idx) => (
                      <TableRow key={article.id}>
                        <TableCell>
                          <div className="flex items-center gap-1">
                            <Button
                              variant="ghost"
                              size="icon"
                              className="h-7 w-7"
                              onClick={() => moveOrder(article.id, 'up')}
                              disabled={idx === 0}
                            >
                              <ArrowUp className="size-3.5" />
                            </Button>
                            <Button
                              variant="ghost"
                              size="icon"
                              className="h-7 w-7"
                              onClick={() => moveOrder(article.id, 'down')}
                              disabled={idx === paginatedArticles.length - 1}
                            >
                              <ArrowDown className="size-3.5" />
                            </Button>
                          </div>
                        </TableCell>
                        <TableCell>
                          {article.coverImage ? (
                            <Image
                              src={imgPath(article.coverImage)}
                              alt={article.title.en}
                              className="w-16 h-10 object-cover rounded-sm border border-border"
                            />
                          ) : (
                            <div className="w-16 h-10 bg-muted rounded-sm flex items-center justify-center text-xs text-muted-foreground">
                              No cover
                            </div>
                          )}
                        </TableCell>
                        <TableCell className="font-medium">
                          <span className="block truncate max-w-[250px]">{article.title.en}</span>
                        </TableCell>
                        <TableCell>
                          <span className="text-xs text-muted-foreground font-mono">{article.slug}</span>
                        </TableCell>
                        <TableCell className="whitespace-nowrap text-sm text-muted-foreground">
                          {article.publishDate}
                        </TableCell>
                        <TableCell>
                          <Switch
                            checked={article.published}
                            onCheckedChange={(checked) => togglePublished(article.id, checked)}
                          />
                        </TableCell>
                        <TableCell className="text-right">
                          <div className="flex items-center justify-end gap-1">
                            <Button
                              variant="ghost"
                              size="icon"
                              className="h-8 w-8"
                              onClick={() => togglePublished(article.id, !article.published)}
                              title={article.published ? 'Unpublish' : 'Publish'}
                            >
                              {article.published ? (
                                <Eye className="size-4 text-success" />
                              ) : (
                                <EyeOff className="size-4 text-muted-foreground" />
                              )}
                            </Button>
                            <Button
                              variant="ghost"
                              size="icon"
                              className="h-8 w-8"
                              onClick={() => openEdit(article)}
                            >
                              <Edit2 className="size-4" />
                            </Button>
                            <Button
                              variant="ghost"
                              size="icon"
                              className="h-8 w-8 hover:text-destructive"
                              onClick={() => setDeleteId(article.id)}
                            >
                              <Trash2 className="size-4" />
                            </Button>
                          </div>
                        </TableCell>
                      </TableRow>
                    ))}
                  </TableBody>
                </Table>
              </div>

              {/* Pagination */}
              {totalPages > 1 && (
                <div className="flex items-center justify-between pt-2">
                  <span className="text-sm text-muted-foreground">
                    Page {currentPage} of {totalPages}
                  </span>
                  <div className="flex items-center gap-1">
                    <Button
                      variant="outline"
                      size="icon"
                      onClick={() => setCurrentPage((p) => Math.max(1, p - 1))}
                      disabled={currentPage === 1}
                      className="h-8 w-8"
                    >
                      <ChevronLeft className="size-4" />
                    </Button>
                    <Button
                      variant="outline"
                      size="icon"
                      onClick={() => setCurrentPage((p) => Math.min(totalPages, p + 1))}
                      disabled={currentPage === totalPages}
                      className="h-8 w-8"
                    >
                      <ChevronRight className="size-4" />
                    </Button>
                  </div>
                </div>
              )}
            </>
          )}
        </CardContent>
      </Card>

      {/* Add/Edit Dialog */}
      <Dialog open={dialogOpen} onOpenChange={setDialogOpen}>
        <DialogContent className="sm:max-w-4xl max-h-[90vh] overflow-y-auto bg-card border-border text-foreground">
          <DialogHeader>
            <DialogTitle className="text-lg flex items-center justify-between">
              <span>{editingId ? 'Edit Article' : 'Add New Article'}</span>
              <Button
                type="button"
                variant="outline"
                size="sm"
                onClick={handleTranslate}
                disabled={translating}
              >
                <Languages className="size-4 mr-1.5" />
                {translating ? 'Translating...' : 'Auto Translate'}
              </Button>
            </DialogTitle>
          </DialogHeader>

          <form onSubmit={handleSubmit} className="space-y-5">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <div className="space-y-2">
                <Label>SEO Slug *</Label>
                <Input
                  value={form.slug}
                  onChange={(e) => setForm((prev) => ({ ...prev, slug: e.target.value }))}
                  placeholder="e.g. how-led-lights-save-energy"
                />
                <p className="text-xs text-muted-foreground">
                  URL-friendly identifier, used in /news/&lt;slug&gt;
                </p>
              </div>
              <div className="space-y-2">
                <Label>Publish Date</Label>
                <Input
                  type="date"
                  value={form.publishDate}
                  onChange={(e) => setForm((prev) => ({ ...prev, publishDate: e.target.value }))}
                />
              </div>
            </div>

            <div className="space-y-2">
              <Label>Title *</Label>
              <I18nInput
                value={form.title}
                onChange={(val) => setForm((prev) => ({ ...prev, title: val }))}
                placeholder="Article title"
              />
            </div>

            <div className="space-y-2">
              <Label>Summary / Excerpt</Label>
              <I18nInput
                value={form.summary}
                onChange={(val) => setForm((prev) => ({ ...prev, summary: val }))}
                placeholder="Short summary of the article"
                multiline
                rows={3}
              />
            </div>

            <div className="space-y-2">
              <Label>Cover Image</Label>
              <div className="flex items-start gap-4">
                <div className="shrink-0">
                  {form.coverImage ? (
                    <Image
                      src={imgPath(form.coverImage)}
                      alt="cover preview"
                      className="w-48 h-28 object-cover rounded-sm border border-border"
                    />
                  ) : (
                    <div className="w-48 h-28 bg-muted/50 rounded-sm border border-dashed border-border flex items-center justify-center text-xs text-muted-foreground">
                      No cover image
                    </div>
                  )}
                </div>
                <div className="space-y-2 flex-1">
                  <Input
                    type="file"
                    accept="image/*"
                    onChange={handleCoverUpload}
                    className="text-sm"
                  />
                  <p className="text-xs text-muted-foreground">
                    Recommended: 16:9 ratio, max 2MB. Use local file path or upload image.
                  </p>
                  <Input
                    value={form.coverImage.startsWith('data:') ? '(uploaded image)' : form.coverImage}
                    onChange={(e) => setForm((prev) => ({ ...prev, coverImage: e.target.value }))}
                    placeholder="Or enter image path / URL"
                    className="text-xs"
                  />
                </div>
              </div>
            </div>

            <div className="space-y-2">
              <Label>Article Content (Rich Text)</Label>
              <RichTextEditor
                value={form.content}
                onChange={(val) => setForm((prev) => ({ ...prev, content: val }))}
                placeholder="Write your article content here..."
                maxHeight="450px"
              />
            </div>

            <div className="pt-4 border-t border-border">
              <h4 className="text-sm font-semibold mb-3">SEO Meta Settings</h4>
              <div className="space-y-3">
                <div>
                  <Label className="text-xs text-muted-foreground">Meta Title</Label>
                  <I18nInput
                    value={form.metaTitle}
                    onChange={(val) => setForm((prev) => ({ ...prev, metaTitle: val }))}
                    placeholder="SEO title (60 characters recommended)"
                  />
                </div>
                <div>
                  <Label className="text-xs text-muted-foreground">Meta Description</Label>
                  <I18nInput
                    value={form.metaDescription}
                    onChange={(val) => setForm((prev) => ({ ...prev, metaDescription: val }))}
                    placeholder="SEO description (160 characters recommended)"
                    multiline
                    rows={2}
                  />
                </div>
              </div>
            </div>

            <div className="flex items-center gap-3">
              <Switch
                id="published-switch"
                checked={form.published}
                onCheckedChange={(checked) => setForm((prev) => ({ ...prev, published: checked }))}
              />
              <Label htmlFor="published-switch">Published</Label>
            </div>

            <DialogFooter>
              <Button
                type="button"
                variant="outline"
                onClick={() => setDialogOpen(false)}
              >
                Cancel
              </Button>
              <Button type="submit">
                {editingId ? 'Update Article' : 'Add Article'}
              </Button>
            </DialogFooter>
          </form>
        </DialogContent>
      </Dialog>

      {/* Delete Confirmation */}
      <AlertDialog open={!!deleteId} onOpenChange={() => setDeleteId(null)}>
        <AlertDialogContent className="bg-card border-border text-foreground">
          <AlertDialogHeader>
            <AlertDialogTitle>Delete Article</AlertDialogTitle>
            <AlertDialogDescription>
              Are you sure you want to delete this article? This action cannot be undone.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>Cancel</AlertDialogCancel>
            <AlertDialogAction
              onClick={handleDelete}
              className="bg-destructive hover:bg-destructive/90 text-destructive-foreground"
            >
              Delete
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </div>
  );
}
